import * as T from 'three';
import {OrbitControls} from './assets/OrbitControls.js';
import {createModel,disposeModel} from './models.js?v=7';
const ease=t=>1-(1-t)**3;
export default class View{
 constructor(container){this.container=container;this.scene=new T.Scene();this.scene.background=new T.Color('#eeeade');this.scene.fog=new T.Fog('#eeeade',90,180);this.renderer=new T.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.22;this.renderer.domElement.setAttribute('aria-label','可拖动旋转和缩放的建筑外观示意模型');this.renderer.domElement.setAttribute('role','img');container.append(this.renderer.domElement);this.camera=new T.PerspectiveCamera(37,1,.1,400);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.dampingFactor=.07;this.controls.enablePan=false;this.controls.minPolarAngle=.08;this.controls.maxPolarAngle=Math.PI*.485;this.controls.autoRotateSpeed=.45;this.scene.add(new T.HemisphereLight(0xf5f0d8,0x879e83,2.4));const sun=new T.DirectionalLight(0xffefd0,3.2);sun.position.set(-25,40,28);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-45,right:45,top:45,bottom:-45,near:1,far:130});sun.shadow.normalBias=.04;sun.shadow.bias=-.0002;this.scene.add(sun);const fill=new T.DirectionalLight(0xc9e0e3,1.1);fill.position.set(30,12,-20);this.scene.add(fill);const ground=new T.Mesh(new T.PlaneGeometry(600,600),new T.MeshStandardMaterial({color:0xeeeade,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.59;ground.receiveShadow=true;this.scene.add(ground);this.active=false;this.model=null;this.clock=new T.Clock();this.transition=0;this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(container);document.addEventListener('visibilitychange',()=>{if(document.hidden)this.renderer.setAnimationLoop(null);else if(this.active)this.startLoop()});this.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();this.pause();this.container.dispatchEvent(new CustomEvent('viewerror',{bubbles:true}))});this.resize()}
 resize(){const {width,height}=this.container.getBoundingClientRect();if(width<1||height<1)return;const previous=this.camera.aspect;this.renderer.setSize(width,height);this.camera.aspect=width/height;this.camera.updateProjectionMatrix();if(this.model&&Math.abs(previous-this.camera.aspect)>.01){const oldDistance=this.distance;this.distance=this.radius*Math.max(1.05,1.4/this.camera.aspect);this.home=new T.Vector3(this.distance*.94,this.distance*.76,this.distance*1.28);if(oldDistance){this.camera.position.sub(this.controls.target).multiplyScalar(this.distance/oldDistance).add(this.controls.target);this.controls.update()}}}
 startLoop(){this.clock.start();this.renderer.setAnimationLoop(()=>{if(!this.active)return;this.controls.update(Math.min(this.clock.getDelta(),.05));this.renderer.render(this.scene,this.camera)})}
 async animateCamera(to,ms){let seq=++this.transition;const start=this.camera.position.clone();this.controls.enabled=false;await new Promise(resolve=>{let t0;const frame=t=>{if(seq!==this.transition){resolve();return}t0??=t;let f=ms?Math.min(1,(t-t0)/ms):1;this.camera.position.lerpVectors(start,to,ease(f));this.camera.lookAt(this.controls.target);if(f<1)requestAnimationFrame(frame);else resolve()};requestAnimationFrame(frame)});this.controls.enabled=true;this.controls.update()}
 async show(type,reduced){this.resize();if(this.model){this.scene.remove(this.model);disposeModel(this.model)}this.model=createModel(type);this.scene.add(this.model);const bounds=new T.Box3().setFromObject(this.model),size=bounds.getSize(new T.Vector3());this.radius=Math.max(size.x,size.z)*.78;this.controls.target.set(0,Math.min(size.y*.28,4),0);this.controls.autoRotate=false;this.controls.minDistance=this.radius*.58;this.controls.maxDistance=this.radius*5;this.active=true;this.distance=this.radius*Math.max(1.05,1.4/this.camera.aspect);this.home=new T.Vector3(this.distance*.94,this.distance*.76,this.distance*1.28);this.camera.position.set(this.distance*.48,this.distance*2.8,this.distance*2);this.startLoop();await this.animateCamera(this.home,reduced?0:1100)}
 async depart(reduced){this.controls.autoRotate=false;await this.animateCamera(new T.Vector3(this.distance*.48,this.distance*2.8,this.distance*2),reduced?0:600)}
 async setView(type){if(!this.model)return;this.controls.autoRotate=false;document.querySelector('#rotate').setAttribute('aria-pressed','false');const p=type==='front'?new T.Vector3(0,this.controls.target.y+this.distance*.16,this.distance*1.75):type==='top'?new T.Vector3(.1,this.distance*1.85,.1):this.home;await this.animateCamera(p,matchMedia('(prefers-reduced-motion: reduce)').matches?0:700)}
 setRotate(v){this.controls.autoRotate=v}
 pause(){this.active=false;this.renderer.setAnimationLoop(null)}
}
